update public.contenu_site set valeur = jsonb_set(valeur, '{paragraphs,1}', to_jsonb($t$Wir führen Sie durch Ouidah, vom portugiesischen Fort bis zum Strand: Erinnerungsorte, Vodun-Tempel, Handwerker, Lagune und Ozean.$t$::text)) where cle = 'DE:fr.welcome' and valeur #>> '{paragraphs,1}' = $t$Wir laden Sie ein, Ouidah ganz nah an seiner Seele zu erleben, ein Ziel, wo Geschichte, Spiritualität, Kultur, Kunst und Natur zusammenkommen, um Ihnen ein authentisches Erlebnis zu bieten.$t$;
