update public.contenu_site set valeur = jsonb_set(valeur, '{8,text}', to_jsonb($t$O mercado de Zobè, perto do forte português, e o do bairro de Kpassè: os nossos guias levam-no até lá, bem como aos artesãos, aos maquis e aos restaurantes de Ouidah.$t$::text)) where cle = 'PT:fr.tenReasons' and valeur #>> '{8,text}' = $t$O mercado de Zobè, perto do forte português, e o do bairro de Kpassè marcam o ritmo da cidade. Os nossos guias levam-no até lá, bem como aos artesãos e aos bons locais para comer em Ouidah, dos pequenos maquis aos restaurantes. É a cidade de hoje, que vive entre duas visitas.$t$ and valeur #>> '{8,slug}' = 'marches';
