update public.contenu_site set valeur = jsonb_set(valeur, '{8,text}', to_jsonb($t$Mache Zobè a, toupre fò pòtigè a, ak mache katye Kpassè a : gid nou yo mennen ou la, lakay atizan yo, nan maquis yo ak nan restoran Ouidah yo.$t$::text)) where cle = 'HT:fr.tenReasons' and valeur #>> '{8,text}' = $t$Mache Zobè a, toupre fò pòtigè a, ansanm ak mache katye Kpassè a, bay vil la ritm li. Gid nou yo mennen ou la, lakay atizan yo ak nan bon kote pou manje nan Ouidah, soti nan ti maquis yo rive nan restoran yo. Se vil jodi a, k ap viv ant de vizit.$t$ and valeur #>> '{8,slug}' = 'marches';
