update public.contenu_site set valeur = jsonb_set(valeur, '{fiche,retraitTexte}', jsonb_build_array(valeur #> '{fiche,retraitTexte,0}')) where cle = 'EN:boutique.boutique' and valeur #> '{fiche,retraitTexte}' = $t$["Pickup in Ouidah or delivery, as chosen at order.","One‑off payment when you order, no deposit. Delivery fees depend on the zone and are shown before payment.","Price in euros or CFA francs at the fixed rate of €1 = 655.957 FCFA; in dollars, indicative, at the rate set by OHT."]$t$::jsonb;
