update public.contenu_site set valeur = jsonb_set(valeur, '{fiche,retraitTexte}', jsonb_build_array(valeur #> '{fiche,retraitTexte,0}')) where cle = 'DE:boutique.boutique' and valeur #> '{fiche,retraitTexte}' = $t$["Abholung in Ouidah oder Lieferung, bei der Bestellung wählbar.","Vollständige Zahlung bei der Bestellung, ohne Anzahlung. Versandkosten je nach Zone, vor der Zahlung angezeigt.","Preise in Euro oder CFA-Franc zum festen Kurs von 1 € = 655,957 FCFA; Dollarpreise dienen der Orientierung und beruhen auf dem von OHT festgelegten Kurs."]$t$::jsonb;
update public.contenu_site set valeur = jsonb_set(valeur, '{fiche,retraitTexte}', jsonb_build_array(valeur #> '{fiche,retraitTexte,0}')) where cle = 'PT:boutique.boutique' and valeur #> '{fiche,retraitTexte}' = $t$["Levantamento em Ouidah ou entrega, à escolha na encomenda.","Pagamento único no momento da encomenda, sem sinal. Portes de envio conforme a zona, indicados antes do pagamento.","Preços em euros ou francos CFA à taxa fixa de 1 € = 655,957 FCFA; em dólares, a título indicativo, à taxa definida pela OHT."]$t$::jsonb;
update public.contenu_site set valeur = jsonb_set(valeur, '{fiche,retraitTexte}', jsonb_build_array(valeur #> '{fiche,retraitTexte,0}')) where cle = 'HT:boutique.boutique' and valeur #> '{fiche,retraitTexte}' = $t$["Vin pran nan Ouidah oswa livrezon, ou chwazi lè w ap fè kòmann nan.","Peman yon sèl kou lè w fè kòmann nan, san avans. Frè livrezon depann de zòn nan, yo parèt anvan peman an.","Pri an ewo oswa an fran CFA nan to fiks 1 € = 655,957 FCFA ; an dola, pou enfòmasyon sèlman, nan to OHT fikse a."]$t$::jsonb;
update public.contenu_site set valeur = jsonb_set(valeur, '{fiche,retraitTexte}', jsonb_build_array(valeur #> '{fiche,retraitTexte,0}')) where cle = 'GCF:boutique.boutique' and valeur #> '{fiche,retraitTexte}' = $t$["Pran Ouidah oben fè livwé, zot ka chwazi lè zot ka komandé.","Péman an sèl kou lè zot ka komandé, san avans. Frè livrézon ka dépann di zòn-lan, yo ka parèt avan péman-lan.","Pri an léwo oben an fran CFA épi to fiks 1 € = 655,957 FCFA ; an dola, pou bay an lidé, épi to OHT fikse-a."]$t$::jsonb;

-- brouillon
update public.contenu_site set brouillon = jsonb_set(brouillon, '{title,1}', to_jsonb($t$sur les lieux de votre Histoire.$t$::text)) where cle = 'fr.welcome' and brouillon #>> '{title,1}' = $t$au cœur de votre Histoire.$t$;
update public.contenu_site set brouillon = jsonb_set(brouillon, '{paragraphs,0}', to_jsonb($t$Ouidah Heritage Tour est une agence de tourisme mémoriel et culturel, à Ouidah.$t$::text)) where cle = 'fr.welcome' and brouillon #>> '{paragraphs,0}' = $t$Ouidah Héritage Tour est bien plus qu'une agence : c'est un engagement pour un tourisme responsable et profondément humain.$t$;
update public.contenu_site set brouillon = jsonb_set(brouillon, '{paragraphs,1}', to_jsonb($t$Nous vous menons dans Ouidah, du fort portugais à la plage : lieux de mémoire, temples vodun, artisans, lagune et océan.$t$::text)) where cle = 'fr.welcome' and brouillon #>> '{paragraphs,1}' = $t$Nous vous invitons à vivre Ouidah au plus près de son âme, une destination où l'histoire, la spiritualité, la culture, l'art et la nature se rencontrent pour vous offrir une expérience authentique.$t$;
update public.contenu_site set brouillon = jsonb_set(brouillon, '{paragraphs,2}', to_jsonb($t$Nous composons chaque voyage à partir de vos questions et de vos envies, et vous accompagnons jusqu'au retour.$t$::text)) where cle = 'fr.welcome' and brouillon #>> '{paragraphs,2}' = $t$Chaque voyage est unique : notre équipe prend soin de vos centres d'intérêt, de vos attentes et de vos besoins. Nous vous accompagnons avant, pendant et après le voyage.$t$;
