update public.contenu_site set brouillon = jsonb_set(brouillon, '{8,text}', to_jsonb($t$Der Markt von Zobè, nahe dem portugiesischen Fort, und der im Viertel Kpassè: Unsere Guides führen Sie dorthin, ebenso zu den Handwerkern, in die Maquis und in die Restaurants von Ouidah.$t$::text)) where cle = 'DE:fr.tenReasons' and brouillon #>> '{8,text}' = $t$Der Markt von Zobè, in der Nähe des portugiesischen Forts, und der im Viertel Kpassè prägen das Leben der Stadt. Unsere Guides führen Sie dorthin, zu den Handwerkern und zu den guten Restaurants von Ouidah, von den Maquis bis zu den Restaurants. Es ist die Stadt von heute, die zwischen zwei Besichtigungen lebt.$t$ and brouillon #>> '{8,slug}' = 'marches';
