update public.contenu_site set brouillon = jsonb_set(brouillon, '{8,text}', to_jsonb($t$Maché Zobè, bò fò pòtigé-a, épi ta katjé Kpassè : gid nou ka mennen zot la, lakay sé atizan-an, adan sé maki-a épi sé rèstoran Ouidah-la.$t$::text)) where cle = 'GCF:fr.tenReasons' and brouillon #>> '{8,text}' = $t$Maché Zobè, bò fò pòtigé-a, épi ta katjé Kpassè ka bay lavi lavil-la ritm li. Gid nou ka mennen zot la, lakay sé atizan-an épi adan sé bon koté manjé Ouidah-la, dépi sé maki-a jik sé rèstoran-an. Sé lavil jòdi-a, tala ki ka viv ant dé vizit.$t$ and brouillon #>> '{8,slug}' = 'marches';
