update public.contenu_site set brouillon = jsonb_set(brouillon, '{fiche,retraitTexte}', jsonb_build_array(brouillon #> '{fiche,retraitTexte,0}')) where cle = 'PT:boutique.boutique' and brouillon #> '{fiche,retraitTexte}' = $t$["Levantamento em Ouidah ou entrega, à escolha na encomenda.","Pagamento único no momento da encomenda, sem sinal. Portes de envio conforme a zona, indicados antes do pagamento.","Preços em euros ou francos CFA à taxa fixa de 1 € = 655,957 FCFA; em dólares, a título indicativo, à taxa definida pela OHT."]$t$::jsonb;
