-- Rubriques à 7 langues (FR dans le code) : si le worker a déjà écrit leurs traductions en base, ces traductions de l'ancien
-- FR masquent les blocs du code et le job terminé ne repart jamais seul. On le remet en file pour retraduire les champs
-- dont le FR a changé (la mémoire garde les autres). services.copiesServices hors périmètre de cette réécriture.
select public.traduction_auto_planifier('contenu', c.cle, true) from public.contenu_site c
  where c.cle in ('suivi.suivi', 'assistant-site.assistantSite', 'blog-site.copiesBlog') and c.valeur is not null;
